// === Tab: mySketch ===
// Selection- I found several that may relate to the class like with audio (like mashups) and movement but some had glitches I didn't know how to fix and I thought this was the most understandable. Although it's a good example of the concept of the class discussion on how much does something need to change in order to make it your own, but also like some artists in the critiques for how they can take older work and make it new and form new ideas or concepts which is seen in a lot of art.
// Aesthetics- (In code below) I loved the original design and I played around with it a little and wanted to keep most things how they are. I wanted to change the background color, but I think the black works a lot better because it makes it look like the lines are moving faster
var num = 1000;
var vx = new Array(num);
var vy = new Array(num);
var x = new Array(num);
var y = new Array(num);
var ax = new Array(num);
var ay = new Array(num);

var magnetism = 20.0; // Made the pull from the mouse key and automatic lines connect faster by adding 10 
var radius = 4.5 ;
var principle = 1; // assigned to a different variable

function setup(){
  createCanvas(windowWidth,windowHeight);
  noStroke(); 
  fill(100); // changed the fill to how quickly the outside lines would connect
  ellipseMode(500); //changed from ellipse mode from radius to a high number in order to make the automatic lines thinner and start as blue then transition to white
	// The line above also made it see-through when creating spread out circles and got rid of the starting circles
  background(0); // I could change the background from the variety of black to white by imputting numbers 1 to 100
  blendMode(ADD);

  for(var i =0; i< num; i++){
    x[i] = random(width);
    y[i] = random(height);
    vx[i] = 0;
    vy[i] = 0;
    ax[i] = 0;
    ay[i] = 0;
  }
}


function draw(){ //Can't be changed or the screen turns white and does nothing
  fill(0,0,0);
  rect(0,0,width,height);

  for(var i=0; i<num; i++){
    var distance = dist(touchX, touchY, x[i], y[i]);
    if(distance > 3){ 
      ax[i] = magnetism * (touchX - x[i]) / (distance * distance); 
      ay[i] = magnetism * (touchY - y[i]) / (distance * distance);
    }
    vx[i] += ax[i];
    vy[i] += ay[i];

    vx[i] = vx[i]*principle; //changed to principle in order to show the variables assigned to it remains the same as long as it's represented to something
    vy[i] = vy[i]*principle;

    x[i] += vx[i];
    y[i] += vy[i];

    var sokudo = dist(0,0,vx[i],vy[i]);
    var r = map(sokudo, 0, 5, 0, 255);
    var g = map(sokudo, 0,5, 64, 255);
    var b = map(sokudo, 0,5, 128, 255);
    fill(r, g, b, 32);
    ellipse(x[i],y[i],1,radius); //Added a numeral in place of radius to make a highlighted circle start as soon as it starts if the person chooses to not move their mouse
  }

}

